CREATE TABLE IF NOT EXISTS clearing_discrepancy (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    biz_date DATE NOT NULL,
    txn_no VARCHAR(64) NOT NULL,
    amount_cents BIGINT NOT NULL,
    reason VARCHAR(128) NOT NULL,
