236	        JsonNode batch = getBatch("2026-09-25");
237	        // 不得双边计额：600 - 600 + 400 = 400
238	        assertEquals(400L, batch.get("totalCents").asLong());
239	        long estimateSum = 0;
240	        long reversalSum = 0;
241	        long settleSum = 0;
242	        for (JsonNode detail : batch.get("details")) {
243	            switch (detail.get("entryType").asText()) {
244	                case "ESTIMATE" -> estimateSum += detail.get("amountCents").asLong();
245	                case "REVERSAL" -> reversalSum += detail.get("amountCents").asLong();
246	                case "SETTLE" -> settleSum += detail.get("amountCents").asLong();
247	                default -> throw new IllegalStateException("unexpected type");
248	            }
