84	    @Test
85	    void concurrentSameKeyEntryReplaysSingleResult() throws Exception {
86	        EntryRequest request = new EntryRequest("req-c1", "T-C1", "CARD-C1", "A",
87	                LocalDateTime.of(2026, 9, 25, 9, 0));
88	        List<EntryResponse> responses = runConcurrently(8, i -> metroService.entry(request));
89	
90	        long fresh = responses.stream().filter(r -> !r.replayed()).count();
91	        assertEquals(1L, fresh, "恰好一个请求实际入账，其余为重放");
92	        for (EntryResponse response : responses) {
93	            assertEquals("T-C1", response.txnNo());
94	            assertEquals("ENTERED", response.status());
95	        }
96	        Integer txnCount = jdbcTemplate.queryForObject(
97	                "SELECT COUNT(*) FROM metro_transaction WHERE txn_no = 'T-C1'", Integer.class);
98	        assertEquals(1, txnCount);
99	        Integer idemCount = jdbcTemplate.queryForObject(
100	                "SELECT COUNT(*) FROM idempotency_record WHERE scope = 'ENTRY' AND request_id = 'req-c1'",
101	                Integer.class);
102	        assertEquals(1, idemCount);
103	    }
104	
105	    @Test
106	    void concurrentDuplicateTxnNoAllowsExactlyOne() throws Exception {
107	        List<Object> outcomes = runConcurrently(8, i -> {
108	            try {
109	                return metroService.entry(new EntryRequest("req-c2-" + i, "T-C2", "CARD-C2", "A",
110	                        LocalDateTime.of(2026, 9, 25, 9, 0)));
111	            } catch (MetroException ex) {
112	                return ex;
113	            }
114	        });
115	        long successes = outcomes.stream().filter(o -> o instanceof EntryResponse).count();
116	        assertEquals(1L, successes, "重复流水号并发下只允许一笔入账");
117	        long conflicts = outcomes.stream()
118	                .filter(o -> o instanceof MetroException)
119	                .map(o -> (MetroException) o)
120	                .filter(ex -> ex.getStatus() == HttpStatus.CONFLICT
