package com.example.starter.metro.dto;

/**
 * 退款申请响应。
 *
 * @param refundNo  退款单号
 * @param txnNo     原交易流水号
 * @param amountCents 本次退款金额（分）
 * @param status    退款单状态（PENDING 待复核）
 * @param version   退款单版本（新建为 1）
 * @param replayed  是否幂等重放命中首次结果
 */
public record RefundApplyResponse(String refundNo, String txnNo, long amountCents,
                                  String status, int version, boolean replayed)
        implements ReplayableResponse<RefundApplyResponse> {

    @Override
    public RefundApplyResponse asReplayed() {
        return new RefundApplyResponse(refundNo, txnNo, amountCents, status, version, true);
    }
}

package com.example.starter.metro.dto;

import java.time.LocalDateTime;
import java.util.List;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 退款双人复核请求：两次调用由两名不同复核人发起，第二次（最终确认）
 * 在同一事务内共同校验两人并占用余额、生成独立负向调整明细。
 *
 * @param requestId       幂等键
 * @param reviewer        复核人工号
 * @param reviewTime      复核精确时刻（Asia/Shanghai）
 * @param expectedVersion 退款单期望版本（首人复核传 1，最终确认传 2）
 */
public record RefundConfirmRequest(
        @NotBlank String requestId,
        @NotBlank String reviewer,
        @NotNull LocalDateTime reviewTime,
        @Positive @NotNull Integer expectedVersion) {

    /** 最终确认响应中的逐线路退款分摊视图（金额为正，合计等于退款金额）。 */
    public record LineAllocation(String lineCode, long refundCents) {
    }

    /** 最终确认成功响应。 */
    public record ConfirmResult(String refundNo, String adjustmentNo, String txnNo, long amountCents,
                                String status, int version, String firstReviewer,
                                String finalReviewer, List<LineAllocation> allocations,
                                boolean replayed)
            implements ReplayableResponse<ConfirmResult> {

        @Override
        public ConfirmResult asReplayed() {
            return new ConfirmResult(refundNo, adjustmentNo, txnNo, amountCents, status, version,
                    firstReviewer, finalReviewer, allocations, true);
        }
    }
}

