        throw new UnsupportedOperationException("待实现");
    }

    /** 封存调账批次（终态，只读）。 */
    public AdjustmentSealResponse sealBatch(AdjustmentSealRequest request) {
        throw new UnsupportedOperationException("待实现");
    }

    /** 查询调账批次视图。 */
    public AdjustmentBatchView batchView(String batchNo) {
        throw new UnsupportedOperationException("待实现");
    }

