        postJson("/api/metro/refunds/batches/open",
                "{\"requestId\":\"ro10b\",\"batchNo\":\"AB10B\",\"openTime\":\"2026-09-26T12:01:00\"}", 200);
        postJson("/api/metro/refunds/batches/include",
